def apply_isolated_2x3_zeroing(grid):
    rows = len(grid)
    cols = len(grid[0])
    result = [row[:] for row in grid]

    to_zero = set()

    for r in range(rows - 2 + 1):
        for c in range(cols - 3 + 1):
            block_non_zero = True
            for dr in range(2):
                for dc in range(3):
                    if grid[r+dr][c+dc] == 0:
                        block_non_zero = False
                        break
                if not block_non_zero:
                    break

            if not block_non_zero:
                continue

            top = True
            if r > 0:
                for dc in range(3):
                    if grid[r-1][c+dc] != 0:
                        top = False
                        break

            bottom = True
            if r+2 < rows:
                for dc in range(3):
                    if grid[r+2][c+dc] != 0:
                        bottom = False
                        break

            left = True
            if c > 0:
                for dr in range(2):
                    if grid[r+dr][c-1] != 0:
                        left = False
                        break

            right = True
            if c+3 < cols:
                for dr in range(2):
                    if grid[r+dr][c+3] != 0:
                        right = False
                        break

            if top and bottom and left and right:
                for dr in range(2):
                    for dc in range(3):
                        to_zero.add((r+dr, c+dc))

