class UF:
    def __init__(self, n):
        self.p = list(range(n))
    def fid(self, i):
        if self.p[i] != i:
            self.p[i] = self.fid(self.p[i])
        return self.p[i]
    def uni(self, i, j):
        pi, pj = self.fid(i), self.fid(j)
        if pi != pj:
            self.p[pi] = pj

def get_comp(grid):
    R, C = len(grid), len(grid[0])
    idx = lambda r, c: r * C + c
    uf = UF(R * C)
    for r in range(R):
        for c in range(C - 1):  # FIXED: don't go out of bounds
            if grid[r][c] != 0 and grid[r][c+1] != 0:
                uf.uni(idx(r, c), idx(r, c+1))
    comps = {}
    for r in range(R):
        for c in range(C):
            if grid[r][c] != 0:
                comps.setdefault(uf.fid(idx(r, c)), []).append((r, c))
    return list(comps.values())

